ires a unique ID, use app.NewWithID()\", nil)\n100|\t}\n101|\treturn a.prefs\n102|}\n103|\n104|func (a *fyneApp) Lifecycle() fyne.Lifecycle {\n105|\treturn a.lifecycle\n106|}\n107|\n108|// New returns a new application instance with the default driver and no unique ID\n109|func New() fyne.App {\n110|\tinternal.LogHint(\"Applications should be created with a unique ID using app.NewWithID()\")\n111|\treturn NewWithID(\"\")\n112|}\n113|\n114|func newAppWithDriver(d fyne.Driver, id string) fyne.App {\n115|\tnewApp := &fyneApp{uniqueID: id, driver: d, exec: execabs.Command, lifecycle: &app.Lifecycle{}}\n116|\tfyne.SetCurrentApp(newApp)\n117|\tnewApp.settings = loadSettings()\n118|\n119|\tnewApp.prefs = newPreferences(newApp)\n120|\tnewApp.storage = &store{a: newApp}\n121|\tif id != \"\" {\n122|\t\tif pref, ok := newApp.prefs.(interface{ load() }); ok {\n123|\t\t\tpref.load()\n124|\t\t}\n125|\n126|\t\troot, _ := newApp.storage.docRootURI()\n127|\t\tnewApp.storage.Docs = &internal.Docs{RootDocURI: root}\n128|\t} else {\n129|\t\tnewApp.storage.Docs = &internal.Docs{} // an empty impl to avoid crashes\n130|\t}\n131|\n132|\tif !d.Device().IsMobile() {\n133|\t\tnewApp.settings.watchSettings()\n134|\t}\n135|\n136|\trepository.Register(\"http\", intRepo.NewHTTPRepository())\n137|\trepository.Register(\"https\", intRepo.NewHTTPRepository())\n138|\n139|\treturn newApp\n140|}"}, {"tool_use_id": "toolu_7Ujjv0LxoFl3AHWvCbB7VL", "content": "由于设置了show_linenos，以下返回信息为：(行号|)内容 。\n[FILE] 140 lines\n1|package widget\n2|\n3|import (\n4|\t\"fyne.io/fyne/v2\"\n5|\t\"fyne.io/fyne/v2/canvas\"\n6|\t\"fyne.io/fyne/v2/internal/widget\"\n7|\t\"fyne.io/fyne/v2/layout\"\n8|\t\"fyne.io/fyne/v2/theme\"\n9|)\n10|\n11|// ToolbarItem represents any interface element that can be added to a toolbar\n12|type ToolbarItem interface {\n13|\tToolbarObject() fyne.CanvasObject\n14|}\n15|\n16|// ToolbarAction is push button style of ToolbarItem\n17|type ToolbarAction struct {\n18|\tIcon        fyne.Resource\n19|\tO